package cn.zhuatech.traceability.deep;import cn.zhuatech.traceability.common.ApiResponse;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/admin/trace-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/batches/{id}/release")ApiResponse<?> release(@PathVariable Long id){return ApiResponse.ok(s.release(id));}@PostMapping("/recalls/{id}/close")ApiResponse<?> close(@PathVariable Long id){return ApiResponse.ok(s.closeRecall(id));}}
